import 'package:flutter/material.dart';import 'package:image_picker/image_picker.dart';import 'package:file_picker/file_picker.dart';import '../database/db_helper.dart';import '../models/book.dart';import '../models/topic_evaluation.dart';import 'package:shamsi_date/shamsi_date.dart';
class TopicEvaluationScreen extends StatefulWidget{const TopicEvaluationScreen({super.key});@override State<TopicEvaluationScreen> createState()=>_TopicEvaluationScreenState();}
class _TopicEvaluationScreenState extends State<TopicEvaluationScreen>{final topic=TextEditingController(),notes=TextEditingController();List<Book> books=[];List<TopicEvaluation> items=[];int? bookId;int rating=3;String? image,audio;@override void initState(){super.initState();load();}Future<void>load()async{books=await DbHelper.instance.getBooks();items=await DbHelper.instance.getEvaluations();if(mounted)setState((){});}Future<void> save()async{if(topic.text.trim().isEmpty)return;await DbHelper.instance.createEvaluation(TopicEvaluation(bookId:bookId,topic:topic.text.trim(),rating:rating,notes:notes.text,imagePath:image,audioPath:audio,evaluatedAt:DateTime.now()));topic.clear();notes.clear();image=null;audio=null;await load();}String date(DateTime d){final j=Jalali.fromDateTime(d);return '${j.year}/${j.month}/${j.day}';}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('ارزیابی فصل و مبحث')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:topic,decoration:const InputDecoration(labelText:'نام فصل یا مبحث',border:OutlineInputBorder())),const SizedBox(height:10),DropdownButtonFormField<int?>(value:bookId,decoration:const InputDecoration(labelText:'کتاب (اختیاری)'),items:[const DropdownMenuItem<int?>(value:null,child:Text('بدون کتاب')), ...books.map((b)=>DropdownMenuItem<int?>(value:b.id,child:Text(b.title)))],onChanged:(v)=>setState(()=>bookId=v)),const SizedBox(height:12),const Text('میزان تسلط'),Wrap(spacing:4,children:List.generate(5,(i)=>IconButton(onPressed:()=>setState(()=>rating=i+1),icon:Icon(i<rating?Icons.star:Icons.star_border,color:Colors.amber,size:30)))),TextField(controller:notes,decoration:const InputDecoration(labelText:'یادداشت',border:OutlineInputBorder()),maxLines:3),Wrap(spacing:8,children:[OutlinedButton.icon(onPressed:()async{final x=await ImagePicker().pickImage(source:ImageSource.gallery);if(x!=null)setState(()=>image=x.path);},icon:const Icon(Icons.image),label:Text(image==null?'تصویر':'تصویر پیوست شد')),OutlinedButton.icon(onPressed:()async{final x=await FilePicker.platform.pickFiles(type:FileType.audio);if(x!=null)setState(()=>audio=x.files.single.path);},icon:const Icon(Icons.mic),label:Text(audio==null?'فایل صوتی':'صوت پیوست شد'))]),FilledButton(onPressed:save,child:const Text('ذخیره ارزیابی')),const Divider(height:30),...items.map((e)=>Card(child:ListTile(title:Text('${e.topic}  ${'★'*e.rating}'),subtitle:Text('${date(e.evaluatedAt)}${e.notes.isEmpty?'':' • ${e.notes}'}'))))]));}}
